    "text": "사랑은 억지로 할 수 없다. 그러나 지금 사랑하지 못한다고 해서 당신 안에 사랑이 없는 것은 아니다. 다만 그 사랑을 가로막는 무언가가 있을 뿐이다.",
    "title": "인생론",
    "author": "레프 톨스토이",
    "genre": "literature"
