    "text": "선택하는 법을 배우는 것은 어렵다. 잘 선택하는 법을 배우는 것은 더 어렵다. 그리고 무한한 가능성의 세계에서 잘 선택하는 법을 배우는 것은 훨씬, 어쩌면 너무 어렵다.",
