    "text": "최근 6개월 중 가장 후회되는 일을 물으면 사람들은 기대에 못 미친 행동을 꼽는다. 하지만 인생 전체를 돌아보며 물으면, 정작 하지 않은 일을 가장 후회한다고 답한다.",
